645	func validate(reg *Registry) error {
646		seen := make(map[string]int, len(reg.Batches))
647		for i, b := range reg.Batches {
648			pos := i + 1
649			if b.Batch == "" || b.Product == "" || b.Unit == "" {
650				return fmt.Errorf("batches record %d (batch %q): batch, product and unit must all be non-empty", pos, b.Batch)
651			}
652			if b.Quantity <= 0 {
653				return fmt.Errorf("batches record %d (batch %q): quantity must be a positive integer", pos, b.Batch)
654			}
655			if first, dup := seen[b.Batch]; dup {
656				return &DuplicateIDError{Batch: b.Batch, First: first, Second: pos}
657			}
658			seen[b.Batch] = pos
659		}
660		return nil
661	}
