1	package batchreg
2	
3	import (
4		"errors"
5		"os"
6		"path/filepath"
7		"strings"
8		"testing"
9	)
10	
11	// Regression net for undecodable field NAMES (object keys) in the two
12	// on-disk JSON sources. A key holding malformed UTF-8 bytes or a lone
13	// surrogate escape must reject the whole operation with its own cause —
14	// "field name encoding invalid" — never the "root/record must be an object"
15	// misdiagnosis, never an "unknown field" verdict against the U+FFFD-
16	// substituted text, and never a silently dropped batch id.
17	//
18	// The BYTE placeholder stands in for a real invalid UTF-8 byte inside the
19	// raw strings; SUR stays a literal lone-surrogate JSON escape.
20	const (
21		keyBYTE = "\x00BYTE\x00"
22		keySUR  = "\x00SUR\x00"
23	)
24	
25	func keyFaultContent(s string) []byte {
26		r := strings.NewReplacer(keyBYTE, string([]byte{0xff}), keySUR, `\ud800`)
27		return []byte(r.Replace(s))
28	}
29	
30	// assertKeyEncodingReason pins the wording that distinguishes the three
31	// rejection causes: the message must say the field NAME encoding is invalid,
32	// and must not read like the not-an-object cause or the unknown-field cause.
33	// It must also never echo a substituted name.
34	func assertKeyEncodingReason(t *testing.T, msg string) {
35		t.Helper()
36		if !strings.Contains(msg, "field name") || !strings.Contains(msg, "UTF-8") {
37			t.Errorf("error must report an invalid field NAME encoding: %v", msg)
38		}
39		if strings.Contains(msg, "must be a JSON object") {
40			t.Errorf("bad field name misreported as not-an-object: %v", msg)
41		}
42		if strings.Contains(msg, "unknown field") {
43			t.Errorf("bad field name misreported as an unknown field: %v", msg)
44		}
45		if strings.Contains(msg, "�") {
46			t.Errorf("error must not echo a U+FFFD-substituted name: %v", msg)
47		}
48	}
49	
50	func TestLoadRejectsUndecodableFieldNames(t *testing.T) {
51		cases := map[string]struct {
52			content string
53			root    bool   // problem is in the root object, not a record
54			pos     int    // 1-based record position when root is false
55			batch   string // batch id the error must cite; "" for none
56		}{
57			"root bad key bytes": {
58				`{"version":1,"batches":[],"su` + keyBYTE + `plier":"S"}`,
59				true, 0, "",
60			},
61			"root lone surrogate escape key": {
62				`{"version":1,"batches":[],"sup` + keySUR + `lier":"S"}`,
63				true, 0, "",
64			},
65			"record bad key after valid batch": {
66				`{"version":1,"batches":[{"batch":"B-002","product":"P","quantity":1,"unit":"kg","su` + keyBYTE + `plier":"S"}]}`,
67				false, 1, "B-002",
68			},
69			"record bad key before valid batch": {
70				`{"version":1,"batches":[{"su` + keyBYTE + `plier":"S","batch":"B-002","product":"P","quantity":1,"unit":"kg"}]}`,
71				false, 1, "B-002",
72			},
73			"second record bad key keeps first record blameless": {
74				`{"version":1,"batches":[
75				 {"batch":"B-001","product":"P","quantity":1,"unit":"kg"},
76				 {"batch":"B-002","product":"P","quantity":2,"unit":"kg","x` + keySUR + `y":1}]}`,
77				false, 2, "B-002",
78			},
79			"registry keeps padded batch id verbatim": {
80				`{"version":1,"batches":[{"batch":" B2 ","su` + keyBYTE + `plier":"S","product":"P","quantity":1,"unit":"kg"}]}`,
81				false, 1, " B2 ",
82			},
83			"duplicated batch cites no id": {
84				`{"version":1,"batches":[{"batch":"B2","batch":"B2","su` + keyBYTE + `plier":"S","product":"P","quantity":1,"unit":"kg"}]}`,
85				false, 1, "",
86			},
87			"non-string batch cites no id": {
88				`{"version":1,"batches":[{"batch":7,"su` + keyBYTE + `plier":"S","product":"P","quantity":1,"unit":"kg"}]}`,
89				false, 1, "",
90			},
91			"badly encoded batch value cites no id": {
92				`{"version":1,"batches":[{"batch":"B` + keyBYTE + `","su` + keySUR + `plier":"S","product":"P","quantity":1,"unit":"kg"}]}`,
93				false, 1, "",
94			},
95			"missing batch cites no id": {
96				`{"version":1,"batches":[{"su` + keyBYTE + `plier":"S","product":"P","quantity":1,"unit":"kg"}]}`,
97				false, 1, "",
98			},
99		}
100		for name, tc := range cases {
101			t.Run(name, func(t *testing.T) {
102				path := filepath.Join(t.TempDir(), "registry.json")
103				content := keyFaultContent(tc.content)
104				if err := os.WriteFile(path, content, 0o644); err != nil {
105					t.Fatal(err)
106				}
107				_, _, err := Load(path)
108				var fe *FormatError
109				if !errors.As(err, &fe) {
110					t.Fatalf("expected FormatError, got %v", err)
111				}
112				if tc.root && fe.Position != 0 {
113					t.Fatalf("root problem must carry no record position, got %d", fe.Position)
114				}
115				if !tc.root && fe.Position != tc.pos {
116					t.Fatalf("position=%d, want %d", fe.Position, tc.pos)
117				}
118				if fe.Field != "" {
119					t.Fatalf("an undecodable name must not be quoted back, got field %q", fe.Field)
120				}
121				if fe.Batch != tc.batch {
122					t.Fatalf("batch=%q, want %q (error: %v)", fe.Batch, tc.batch, err)
123				}
124				msg := err.Error()
125				assertKeyEncodingReason(t, msg)
126				if !strings.Contains(msg, path) {
127					t.Fatalf("error must name the file path: %v", msg)
128				}
129				if tc.root && !strings.Contains(msg, "root object") {
130					t.Fatalf("root problem must be located at the root object: %v", msg)
131				}
132				// The rejected file must stay exactly as it was.
133				after, rerr := os.ReadFile(path)
134				if rerr != nil || string(after) != string(content) {
135					t.Fatal("rejected registry was modified")
136				}
137			})
138		}
139	}
140	
141	func TestParseManifestRejectsUndecodableFieldNames(t *testing.T) {
142		cases := map[string]struct {
143			content string
144			pos     int
145			batch   string
