93		writeFile(t, manifest, `[{"batch":"B1","product":"P","quantity":1,"unit":"kg"}]`)
94	
95		// Pin a distinctive past mtime so any rewrite is observable even on
96		// filesystems with coarse timestamp granularity.
97		pinned := time.Date(2001, time.February, 3, 4, 5, 6, 0, time.UTC)
98		if err := os.Chtimes(registry, pinned, pinned); err != nil {
99			t.Fatal(err)
