130	func TestBatchImportCLIRejectsAndPreserves(t *testing.T) {
131		cases := map[string]string{
132			"empty file":      "",
133			"empty array":     "[]",
134			"object":          "{}",
135			"quantity string": `[{"batch":"B","product":"P","quantity":"1","unit":"kg"}]`,
136			"quantity float":  `[{"batch":"B","product":"P","quantity":1.0,"unit":"kg"}]`,
137			"missing field":   `[{"batch":"B","product":"P","quantity":1}]`,
138			"unknown field":   `[{"batch":"B","product":"P","quantity":1,"unit":"kg","x":1}]`,
139			"blank batch":     `[{"batch":"  ","product":"P","quantity":1,"unit":"kg"}]`,
140		}
141		for name, content := range cases {
142			t.Run(name, func(t *testing.T) {
143				dir := t.TempDir()
144				registry := filepath.Join(dir, "reg.json")
