	registries := map[string]string{
		"duplicate empty batches": `{"version":1,"batches":[{"batch":"B1","product":"P","quantity":1,"unit":"kg"}],"batches":[]}`,
		"duplicate version":       `{"version":1,"version":1,"batches":[]}`,
